  1478→        // 连接WebSocket
  1479→        function connect() {
  1480→            const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  1481→            ws = new WebSocket(`${protocol}//${window.location.host}`);
  1482→
  1483→            ws.onopen = () => {
  1484→                console.log('WebSocket已连接');
  1485→                // 连接后立即获取牌桌列表
  1486→                ws.send(JSON.stringify({ type: 'getTableList' }));
  1487→            };
  1488→
  1489→            ws.onmessage = (event) => {
  1490→                const data = JSON.parse(event.data);
  1491→                handleMessage(data);
  1492→            };
  1493→
  1494→            ws.onclose = () => {
  1495→                console.log('WebSocket已断开');
  1496→                setTimeout(() => {
  1497→                    if (playerId) {
  1498→                        connect();
  1499→                    }
  1500→                }, 3000);
  1501→            };
  1502→
  1503→            ws.onerror = (error) => {
  1504→                console.error('WebSocket错误:', error);
  1505→            };
  1506→        }
  1507→
  1508→        // 处理消息
  1509→        function handleMessage(data) {
  1510→            switch (data.type) {
  1511→                case 'loginSuccess':
  1512→                    playerId = data.playerId;
  1513→                    playerName = data.playerName;
  1514→                    // 登录成功后获取牌桌列表
  1515→                    if (ws && ws.readyState === WebSocket.OPEN) {
  1516→                        ws.send(JSON.stringify({ type: 'getTableList' }));
  1517→                    }
  1518→                    break;
  1519→
  1520→                case 'tableList':
  1521→                    renderTableList(data.tables);
  1522→                    break;
  1523→
  1524→                case 'playerList':
  1525→                    renderPlayerList(data);
  1526→                    break;
  1527→
  1528→                case 'dealStart':
  1529→                    // 开始发牌动画
  1530→                    showDealAnimation();
  1531→                    break;
  1532→
  1533→                case 'gameState':
  1534→                    gameState = data.data;
  1535→                    myIndex = gameState.myIndex;
  1536→                    console.log('收到游戏状态:', gameState);
  1537→                    console.log('我的手牌:', gameState.myHand);
  1538→                    console.log('手牌数量:', gameState.myHand ? gameState.myHand.length : 0);
  1539→                    showGame();  // 确保显示游戏界面
  1540→                    updateGameUI();
  1541→                    break;
  1542→
  1543→                case 'message':
  1544→                    addChatMessage(data.text);
  1545→                    break;
  1546→
  1547→                case 'error':
  1548→                    alert(data.message);
  1549→                    break;

