const ARROWS = ['中', '发', '白'];

// 创建一副麻将牌
function createDeck() {
    const deck = [];

    // 筒条万 (每种4张)
    for (const suit of SUITS) {
        for (const rank of RANKS) {
            for (let i = 0; i < 4; i++) {
