constructor(id, tableNumber) {
    this.id = id;
    this.tableNumber = tableNumber;
    this.players = new Map(); // playerId -> player info
    this.spectators = new Map();
    this.maxPlayers = 4;
    this.gameTimer = null; // 游戏计时器
    this.lastSeatShuffleTime = Date.now(); // 上次换座位时间
    this.sessionStartTime = Date.now(); // 会话开始时间

    this.gameState = {
        started: false,
        currentPlayer: 0, // 0-3, 当前出牌玩家索引
        dealer: 0, // 庄家索引
        deck: [], // 牌堆
        hands: {}, // playerId -> cards[]
        wildCard: null, // 万能牌
        discardedPile: [], // 打出的牌
        showedCards: {}, // playerId -> { fa: [], gang: [] }
        faUsed: {}, // playerId -> 玩家是否已换过发
        lastDrawn: null, // 最后摸的牌
        gameStartTime: null, // 游戏开始时间
        totalGameTime: 0 // 游戏总时长（秒）
    };
}

// 获取按座位排序的玩家ID数组
getSortedPlayerIds() {
    return Array.from(this.players.entries())
        .sort((a, b) => a[1].seatNum - b[1].seatNum)
        .map(([id]) => id);
}

// 添加玩家
addPlayer(ws, playerId, playerName, seatNum = null) {
    if (this.players.size >= this.maxPlayers) return false;
    if (this.gameState.started) return false;

    let actualSeat;
    if (seatNum !== null && seatNum >= 1 && seatNum <= 4) {
        const occupied = Array.from(this.players.values()).some(p => p.seatNum === seatNum);
        if (occupied) return false;
        actualSeat = seatNum;
    } else {
        const occupiedSeats = new Set(Array.from(this.players.values()).map(p => p.seatNum));
        for (let i = 1; i <= 4; i++) {
            if (!occupiedSeats.has(i)) {
                actualSeat = i;
                break;
            }
        }
    }

    this.players.set(playerId, {
        ws,
        id: playerId,
        name: playerName,
        seatNum: actualSeat,
        ready: false,
        isAI: false
    });

    return true;
}

// 移除玩家
removePlayer(playerId) {
    this.players.delete(playerId);
    return this.players.size === 0;
}

// 检查是否所有玩家都已断开连接
isAllPlayersDisconnected() {
    if (this.players.size === 0) return true;
    for (const player of this.players.values()) {
        if (player.ws && player.ws.readyState === WebSocket.OPEN) {
            return false;
        }
    }
    return true;
}

// 设置准备状态
setPlayerReady(playerId, ready) {
    const player = this.players.get(playerId);
    if (player) {
        player.ready = ready;
        this.broadcastPlayerList();
        this.checkStartGame();
    }
}

// 检查是否可以开始游戏
checkStartGame() {
    const allReady = Array.from(this.players.values()).every(p => p.ready);
    // 测试模式：1人即可开始，正式模式改为4
    if (allReady && this.players.size >= 1 && !this.gameState.started) {
        // 检查是否需要随机换座位（每隔1小时）
        const timeSinceLastShuffle = Date.now() - this.lastSeatShuffleTime;
        if (timeSinceLastShuffle >= 3600000) { // 1小时 = 3600000毫秒
            this.randomizeSeats();
            this.lastSeatShuffleTime = Date.now();
            this.broadcastMessage('⏰ 游戏已进行1小时，座位已随机更换！');
        }
        this.startGame();
    }
}

// 随机换座位
randomizeSeats() {
    const playerList = Array.from(this.players.values());
    const seats = [1, 2, 3, 4];

    // 洗牌座位
    for (let i = seats.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [seats[i], seats[j]] = [seats[j], seats[i]];
    }

    // 分配新座位
    playerList.forEach((player, index) => {
        player.seatNum = seats[index];
    });

    console.log(`牌桌${this.tableNumber} 座位已随机更换`);
    this.broadcastPlayerList();
}

// 开始游戏
startGame() {
    this.gameState.started = true;
    this.gameState.gameStartTime = Date.now();
    this.gameState.totalGameTime = 0;

    // 启动游戏计时器（每秒更新）
    this.gameTimer = setInterval(() => {
        if (this.gameState.started) {
            this.gameState.totalGameTime = Math.floor((Date.now() - this.gameState.gameStartTime) / 1000);
        }
    }, 1000);

    // 洗牌
    this.gameState.deck = shuffle(createDeck());

    // 确定万能牌（随机翻一张）
    const wildIndex = Math.floor(Math.random() * this.gameState.deck.length);
    this.gameState.wildCard = this.gameState.deck[wildIndex];

    // 初始化手牌和展示区
    const playerIds = this.getSortedPlayerIds();

