// ==================== WebSocket连接处理 ====================
wss.on('connection', (ws) => {
    let playerId = null;
    let playerName = null;
    let currentTableId = null;

    console.log('新客户端连接');

    ws.on('message', (data) => {
        try {
            const msg = JSON.parse(data);

            switch (msg.type) {
                case 'login':
                    playerId = `player_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
                    playerName = msg.name || '玩家';

                    // 添加到已登录客户端集合
                    loggedInClients.add(ws);

                    ws.send(JSON.stringify({
                        type: 'loginSuccess',
                        playerId,
                        playerName
                    }));

                    // 发送牌桌列表
                    sendTableList(ws);
                    break;

                case 'getTableList':
                    sendTableList(ws);
                    break;

                case 'createTable':
                    const newTable = createTable();
                    // 加入牌桌
                    if (joinTable(ws, playerId, playerName, newTable.id, msg.seatNum)) {
                        currentTableId = newTable.id;
                    }
                    // 广播牌桌列表更新给所有人
                    broadcastTableList();
                    break;

                case 'joinTable':
                    if (joinTable(ws, playerId, playerName, msg.tableId, msg.seatNum)) {
                        currentTableId = msg.tableId;
                        // 广播牌桌列表更新给所有人
                        broadcastTableList();
                    }
                    break;

                case 'ready':
                    if (currentTableId) {
                        const table = tables.get(currentTableId);
                        if (table) {
                            table.setPlayerReady(playerId, msg.ready);
                        }
                    }
                    break;

                case 'play':
                    if (currentTableId) {
                        const table = tables.get(currentTableId);
                        if (table && table.getCurrentPlayerId() === playerId) {
                            if (table.playCard(playerId, msg.cardId)) {
                                table.broadcastGameState();
                            }
                        }
                    }
                    break;

                case 'changeFa':
                    if (currentTableId) {
                        const table = tables.get(currentTableId);
                        if (table && table.getCurrentPlayerId() === playerId) {
                            const result = table.changeFa(playerId);
                            if (result) {
                                table.broadcastMessage(`${playerName} 换了一张"發"`);
                                table.broadcastGameState();
                            }
                        }
                    }
                    break;

                case 'gang':
                    if (currentTableId) {
                        const table = tables.get(currentTableId);
                        if (table && table.getCurrentPlayerId() === playerId) {
                            const result = table.doGang(playerId, msg.cardId);
                            if (result) {
                                table.broadcastMessage(`${playerName} 暗杠！`);
                                table.broadcastGameState();
                            }
                        }
                    }
                    break;

                case 'draw':
                    if (currentTableId) {
                        const table = tables.get(currentTableId);
                        if (table && table.getCurrentPlayerId() === playerId) {
                            const card = table.drawCard(playerId);
                            if (card) {
                                table.broadcastGameState();
                            } else {
                                table.broadcastMessage('牌堆已空，流局！');
                            }
                        }
                    }
                    break;

                case 'chat':
                    if (currentTableId) {
                        const table = tables.get(currentTableId);
                        if (table) {
                            table.broadcastMessage(`${playerName}: ${msg.text}`);
                        }
                    }
                    break;
            }
        } catch (e) {
            console.error('消息处理错误:', e);
        }
    });

    ws.on('close', () => {
        console.log('客户端断开:', playerName);

        // 从已登录客户端集合中移除
        loggedInClients.delete(ws);

        if (currentTableId && playerId) {
            const table = tables.get(currentTableId);
            if (table) {
                // 标记玩家断开
                const player = table.players.get(playerId);
                if (player) {
                    player.ws = null;
                    player.ready = false;
                }

