// 检查是否可以开始游戏
checkStartGame() {
    const allReady = Array.from(this.players.values()).every(p => p.ready);
    // 测试模式：1人即可开始，正式模式改为4
    if (allReady && this.players.size >= 1 && !this.gameState.started) {
        // 检查是否需要随机换座位（每隔1小时）
        const timeSinceLastShuffle = Date.now() - this.lastSeatShuffleTime;
        if (timeSinceLastShuffle >= 3600000) { // 1小时 = 3600000毫秒
            this.randomizeSeats();
            this.lastSeatShuffleTime = Date.now();
            this.broadcastMessage('⏰ 游戏已进行1小时，座位已随机更换！');
        }
        this.startGame();
    }
}

// 随机换座位
randomizeSeats() {
