        .map(([id]) => id);
}

// 处理骰子掷出
handleDiceRoll(playerId, values) {
    return this.rollDice(playerId, values);
}

// 一局结束
endRound(winnerId) {
    this.gameState.roundPhase = 'ended';
    this.lastWinner = winnerId;
