    // 重置所有玩家的准备状态
    for (const player of this.players.values()) {
        player.ready = false;
    }

    this.broadcastMessage(`第${this.currentRound}局结束！请所有玩家准备开始下一局`);
    this.broadcastPlayerList();
}

// 局间准备
setRoundReady(playerId, ready) {
    if (this.gameState.roundPhase !== 'ended') return;

