        // 第二次掷骰子
        this.diceState.secondRoll = { playerId, playerName: player.name, values };
        this.diceState.rollPhase = 3;

        this.broadcastMessage(`🎲 ${player.name} 掷出 ${values[0]}+${values[1]}=${values[0]+values[1]} 点`);

        // 确定抓牌位置和癞子
        this.determineWildCard();

