// 确定万能牌（癞子）和抓牌位置 - 根据骰子结果
determineWildCard() {
    const firstSum = this.diceState.firstRoll.values[0] + this.diceState.firstRoll.values[1];
    const secondSum = this.diceState.secondRoll.values[0] + this.diceState.secondRoll.values[1];
    const total = firstSum + secondSum;

    console.log(`第1次骰子: ${firstSum}, 第2次骰子: ${secondSum}, 总计: ${total}`);

    // 牌墙布局：每个玩家面前17墩牌（每墩2张），按逆时针排列
    // 座位1(东) -> 座位4(北) -> 座位3(西) -> 座位2(南) -> 座位1(东)
    // 牌墙索引：0-33(东), 34-67(北), 68-101(西), 102-135(南)
    // 每个方位17墩，每墩2张牌

    // 第1次骰子决定开始方位（1=东, 2=南, 3=西, 4=北，按掷骰者座位数）
    // 但实际上应该按方位：东(1号位)=1, 南(2号位)=2, 西(3号位)=3, 北(4号位)=4
    const playerIds = this.getSortedPlayerIds();
    const firstRollerSeat = this.players.get(this.diceState.firstRoll.playerId)?.seatNum || 1;

    // 根据第一次骰子确定从哪个方位开始数
    // 逆时针方向：东(1) -> 北(4) -> 西(3) -> 南(2) -> 东(1)
    const seatToDirection = { 1: '东', 2: '南', 3: '西', 4: '北' };
    const directionOrder = [1, 4, 3, 2]; // 逆时针顺序

    // 第1次骰子点数决定从哪个方位开始（从掷骰者的方位开始数）
    const startDirectionIndex = directionOrder.indexOf(firstRollerSeat);
    const countDirection = (startDirectionIndex + firstSum - 1) % 4;
    const startDirection = directionOrder[countDirection];

    console.log(`开始方位: ${seatToDirection[startDirection]} (座位${startDirection})`);

    // 计算从开始方位最左边数起，数total墩
    // 每个方位17墩
    const pilesPerDirection = 17;
    let remainingPiles = total;
    let currentDirection = startDirection;
    let directionIdx = directionOrder.indexOf(currentDirection);

    // 数牌墩
    while (remainingPiles > pilesPerDirection) {
        remainingPiles -= pilesPerDirection;
        directionIdx = (directionIdx + 1) % 4;
        currentDirection = directionOrder[directionIdx];
    }

    // 确定抓牌起始位置
    // 抓牌从第remainingPiles墩的下一墩开始
    const drawPile = remainingPiles; // 第几墩（1-17）
    const drawDirection = currentDirection;

    console.log(`抓牌位置: ${seatToDirection[drawDirection]}方第${drawPile}墩后开始`);

    // 确定癞子
    // 抓牌那墩的逆时针玩家面前的牌墩从右往左数第一次骰子的数量
    const drawDirectionIdx = directionOrder.indexOf(drawDirection);
    const laiziDirectionIdx = (drawDirectionIdx + 1) % 4; // 逆时针下一个
    const laiziDirection = directionOrder[laiziDirectionIdx];

    // 从右往左数第firstSum张牌（每墩2张，所以是第firstSum*2-1和firstSum*2张）
    // 但实际上翻开的是第firstSum墩的上面那张牌
    const laiziPile = pilesPerDirection - firstSum + 1; // 从右往左数

    console.log(`癞子位置: ${seatToDirection[laiziDirection]}方第${laiziPile}墩（从右往左数第${firstSum}墩）`);

    // 计算牌堆中的实际索引
    // 牌墙按 [东17墩][北17墩][西17墩][南17墩] 排列
    const directionToOffset = { 1: 0, 4: 17, 3: 34, 2: 51 }; // 座位到牌墩偏移
    const laiziPileIndex = directionToOffset[laiziDirection] + (laiziPile - 1);

    // 每墩2张牌，取上面那张（索引*2）
    const laiziCardIndex = laiziPileIndex * 2;

    if (laiziCardIndex >= 0 && laiziCardIndex < this.gameState.deck.length) {
        this.gameState.wildCard = this.gameState.deck[laiziCardIndex];
        console.log(`癞子牌索引: ${laiziCardIndex}, 癞子: ${cardName(this.gameState.wildCard)}`);
    } else {
        // 备用：随机选择
        const wildIndex = total % this.gameState.deck.length;
        this.gameState.wildCard = this.gameState.deck[wildIndex];
        console.log(`癞子索引超出范围，使用备用计算: ${cardName(this.gameState.wildCard)}`);
    }

    // 保存抓牌信息用于发牌
    this.gameState.drawInfo = {
        startDirection,
        drawDirection,
        drawPile,
        totalPiles: total
    };
}

