        const windOrder = ['东', '南', '西', '北'];
        const currentIndex = windOrder.indexOf(shownCard.rank);
        const nextIndex = (currentIndex + 1) % 4;
        return {
            suit: '风',
            rank: windOrder[nextIndex],
