                '.jpg': 'image/jpeg',
                '.jpeg': 'image/jpeg',
                '.png': 'image/png',
                '.gif': 'image/gif'
            };
            res.writeHead(200, {
                'Content-Type': contentTypes[ext] || 'application/octet-stream'
            });
            res.end(data);
        });
