/* 牌墙样式 */
.wall-container {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 500px;
    height: 400px;
    pointer-events: none;
    z-index: 0;
}

.wall-section {
    position: absolute;
    display: flex;
    gap: 2px;
}

.wall-top {
    top: 60px;
    left: 50%;
    transform: translateX(-50%);
    flex-direction: row;
}

.wall-bottom {
    bottom: 60px;
    left: 50%;
    transform: translateX(-50%);
    flex-direction: row-reverse;
}

.wall-left {
    left: 80px;
    top: 50%;
    transform: translateY(-50%);
    flex-direction: column;
}

.wall-right {
    right: 80px;
    top: 50%;
    transform: translateY(-50%);
    flex-direction: column-reverse;
}

.wall-pile {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.wall-pile.horizontal {
    flex-direction: row;
}

.wall-tile {
    width: 18px;
    height: 24px;
    background: linear-gradient(180deg, #2E7D32, #1B5E20);
    border: 1px solid #0D3D0D;
    border-radius: 2px;
    margin: -6px 0 0 0;
    box-shadow: 1px 1px 2px rgba(0,0,0,0.3);
}

.wall-section.wall-top .wall-tile,
.wall-section.wall-bottom .wall-tile {
    margin: 0 0 0 -6px;
}

.wall-tile.empty {
    background: transparent;
    border: 1px dashed rgba(255,255,255,0.2);
    box-shadow: none;
}

