/* 牌墙样式 */
.wall-container {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 560px;
    height: 480px;
    pointer-events: none;
    z-index: 0;
}

.wall-section {
    position: absolute;
    display: flex;
    gap: 1px;
}

/* 上方牌墙（北-3号位）- 水平排列，17墩 */
.wall-top {
    top: 40px;
    left: 50%;
    transform: translateX(-50%);
    flex-direction: row;
}

/* 下方牌墙（南-1号位）- 水平排列，17墩 */
.wall-bottom {
    bottom: 40px;
    left: 50%;
    transform: translateX(-50%);
    flex-direction: row-reverse;
}

/* 左方牌墙（西-4号位）- 垂直排列，17墩 */
.wall-left {
    left: 40px;
    top: 50%;
    transform: translateY(-50%);
    flex-direction: column;
}

/* 右方牌墙（东-2号位）- 垂直排列，17墩 */
.wall-right {
    right: 40px;
    top: 50%;
    transform: translateY(-50%);
    flex-direction: column-reverse;
}

/* 牌墩 - 两张牌叠在一起 */
.wall-pile {
    position: relative;
    width: 22px;
    height: 32px;
}

/* 牌墩中的单张牌 */
.wall-tile {
    position: absolute;
    width: 22px;
    height: 32px;
    background: linear-gradient(180deg, #3a8f3a 0%, #2E7D32 50%, #1B5E20 100%);
    border: 1px solid #0D3D0D;
    border-radius: 3px;
    box-shadow: 1px 1px 3px rgba(0,0,0,0.4);
}

/* 上面的牌 - 偏移一点形成层叠效果 */
.wall-tile.top-tile {
    top: 0;
    left: 0;
    z-index: 2;
}

/* 下面的牌 */
.wall-tile.bottom-tile {
    top: 3px;
    left: 3px;
    z-index: 1;
}

/* 左右两边的牌墩 - 需要旋转 */
.wall-left .wall-pile,
.wall-right .wall-pile {
    width: 32px;
    height: 22px;
}

.wall-left .wall-tile,
.wall-right .wall-tile {
    width: 32px;
    height: 22px;
}

.wall-left .wall-tile.top-tile,
.wall-right .wall-tile.top-tile {
    left: 0;
    top: 0;
}

.wall-left .wall-tile.bottom-tile {
    left: 3px;
    top: 3px;
}

.wall-right .wall-tile.bottom-tile {
    left: -3px;
    top: 3px;
}

.wall-tile.empty {
    background: transparent;
    border: 1px dashed rgba(255,255,255,0.2);
    box-shadow: none;
}

