input.new_string:
/* 牌墙样式 */
.wall-container {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 600px;
    height: 500px;
    pointer-events: none;
    z-index: 0;
}

.wall-section {
    position: absolute;
    display: flex;
    gap: 1px;
}

/* 上方牌墙（北-3号位）- 水平排列17墩 */
.wall-top {
    top: 50px;
    left: 50%;
    transform: translateX(-50%);
    flex-direction: row;
}

/* 下方牌墙（南-1号位）- 水平排列17墩 */
.wall-bottom {
    bottom: 50px;
    left: 50%;
    transform: translateX(-50%);
    flex-direction: row-reverse;
}

/* 左方牌墙（西-4号位）- 垂直排列17墩 */
.wall-left {
    left: 60px;
    top: 50%;
    transform: translateY(-50%);
    flex-direction: column;
}

/* 右方牌墙（东-2号位）- 垂直排列17墩 */
.wall-right {
    right: 60px;
    top: 50%;
    transform: translateY(-50%);
    flex-direction: column-reverse;
}

/* 牌墩容器 - 每墩两张牌叠在一起 */
.wall-pile {
    position: relative;
    width: 24px;
    height: 34px;
}

/* 左右两边的牌墩 - 需要旋转90度 */
.wall-left .wall-pile,
.wall-right .wall-pile {
    width: 34px;
    height: 24px;
}

/* 牌墩中的单张牌 */
.wall-tile {
    position: absolute;
    background: linear-gradient(180deg, #4a9f4a 0%, #2E7D32 50%, #1B5E20 100%);
    border: 1px solid #0D3D0D;
    border-radius: 3px;
    box-shadow: 1px 2px 3px rgba(0,0,0,0.4);
}

/* 上下两边的牌 - 竖向 */
.wall-top .wall-tile,
.wall-bottom .wall-tile {
    width: 24px;
    height: 34px;
}

/* 上面的牌 - 在正常位置 */
.wall-top .wall-tile.top-tile,
.wall-bottom .wall-tile.top-tile {
    top: 0;
    left: 0;
    z-index: 2;
}

/* 下面的牌 - 偏移形成层叠 */
.wall-top .wall-tile.bottom-tile,
.wall-bottom .wall-tile.bottom-tile {
    top: 4px;
    left: 4px;
    z-index: 1;
}

/* 左右两边的牌 - 横向 */
.wall-left .wall-tile,
.wall-right .wall-tile {
    width: 34px;
    height: 24px;
}

/* 上面的牌 */
.wall-left .wall-tile.top-tile,
.wall-right .wall-tile.top-tile {
    left: 0;
    top: 0;
    z-index: 2;
}

/* 下面的牌 - 偏移形成层叠 */
.wall-left .wall-tile.bottom-tile {
    left: 4px;
    top: 4px;
    z-index: 1;
}

.wall-right .wall-tile.bottom-tile {
    left: -4px;
    top: 4px;
    z-index: 1;
}

.wall-tile.empty {
    background: transparent !important;
    border: 1px dashed rgba(255,255,255,0.3) !important;
    box-shadow: none !important;
}

.wall-tile.shown {
    background: linear-gradient(180deg, #FFD700, #FFA000) !important;
    border-color: #FF8F00 !important;
    box-shadow: 0 0 8px rgba(255,215,0,0.6) !important;
}

