/* ==================== 牌墙样式 ==================== */
.wall-container {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 620px;
    height: 520px;
    pointer-events: none;
    z-index: 0;
}

