    const playerIds = this.getSortedPlayerIds();
    const firstRollerIndex = playerIds.indexOf(this.diceState.currentRoller);

    // 逆时针：索引+1是下家（逆时针方向）
    // 座位1→座位4→座位3→座位2→座位1（逆时针）
    // 在数组中：0→3→2→1→0
    const secondRollerIndex = (firstRollerIndex + 1) % 4;
    return playerIds[secondRollerIndex];
}

