            if (!this.cycleStartTime || (Date.now() - this.cycleStartTime >= this.cycleDuration)) {
                this.cycleStartTime = Date.now();
                this.currentRound = 0;
                console.log(`牌桌${this.tableNumber} 开始新周期`);
            }
            this.startDicePhase();
